import marketInventory from "../src/lib/market-inventory-data";
import { encodePortableJson } from "../src/lib/portable-string-codec";
import fs from "node:fs";
import { validateCatalogueIssues } from "../src/lib/validate-catalogue-issues";
import { storePortablePacks } from "../src/lib/portable-packs";
import path from "node:path";
import { build } from "esbuild";
import {
  catalogue,
  pickerCatalogue,
  pack,
  research,
  counts,
} from "../src/lib/data";
async function main() {
  const root = process.cwd();
  const result = await build({
    entryPoints: ["src/portable/entry.tsx"],
    bundle: true,
    minify: true,
    write: false,
    format: "iife",
    platform: "browser",
    target: ["es2022"],
    define: {
      "process.env.NODE_ENV": '"production"',
      "process.env.NEXT_PUBLIC_SITE_URL": '""',
    },
    alias: {
      "next/link": path.join(root, "src/portable/link.tsx"),
      "next/image": path.join(root, "src/portable/image.tsx"),
      "next/navigation": path.join(root, "src/portable/navigation.ts"),
      "@/lib/data": path.join(root, "src/portable/data.ts"),
      "@/lib/market-inventory-data": path.join(
        root,
        "src/portable/market-inventory-data.ts",
      ),
      "@/lib/chapter-art-src": path.join(
        root,
        "src/portable/chapter-art-src.ts",
      ),
    },
  });
  const d = research();
  const cars = catalogue();
  const issueErrors = validateCatalogueIssues(cars);
  if (issueErrors.length) throw new Error(issueErrors.join("\n"));
  const snapshot = { data: d, cars };
  const data = {
    marketInventory,
    cars: pickerCatalogue(),
    packs: storePortablePacks(
      Object.fromEntries(cars.map((c) => [c.id, pack(c.id, snapshot)])),
    ),
    research: {
      sources: d.sources,
      criteria: d.criteria,
      publication_issues: d.publication_issues,
      trim_equipment: d.trim_equipment,
    },
    counts: counts(),
    art: Object.fromEntries(
      fs
        .readdirSync("public/media/chapters")
        .filter((file) => file.endsWith(".svg"))
        .map((file) => [
          path.basename(file, ".svg"),
          `data:image/svg+xml;base64,${fs.readFileSync(path.join("public/media/chapters", file)).toString("base64")}`,
        ]),
    ),
  };
  const { json } = encodePortableJson(JSON.stringify(data), 32);
  const js = result.outputFiles[0].text.replaceAll("</script", "<\\/script");
  const css = fs.readFileSync("src/app/globals.css", "utf8");
  const page = (flag: string, title: string) =>
    `<!doctype html><html lang="en-AU"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex"><title>${title}</title><style>${css}</style></head><body><div id="root"></div><noscript>This interactive comparison needs JavaScript enabled.</noscript><script id="ev-data" type="application/json">${json}</script><script>${flag}${js}</script></body></html>`;
  // Preserve the original Model Y hero above discovery; keep index-b.html as an alias.
  const htmlB = page(
    "window.__EV_B=true;",
    "Roadmark · Discover your kind of electric",
  );
  fs.writeFileSync("index.html", htmlB);
  fs.mkdirSync("public", { recursive: true });
  fs.writeFileSync("public/index.html", htmlB);
  fs.writeFileSync("index-b.html", htmlB);
  fs.writeFileSync("public/index-b.html", htmlB);
  console.log(
    `Portable Roadmark experience written (${(Buffer.byteLength(htmlB) / 1e6).toFixed(2)} MB).`,
  );
  console.log(
    "index.html and index-b.html retain the Model Y hero above discovery; the original comparison is also available at ?page=/b.",
  );
}
main().catch((error) => {
  console.error(error);
  process.exitCode = 1;
});

"use client";
import { matchesSearch } from "@/lib/search";
import { buyerDisplayCopy } from "@/lib/buyer-display-copy";
import { useState } from "react";
import Link from "next/link";
import inventory from "@/lib/market-inventory-data";
import { RoadmarkLogo } from "./roadmark-logo";
const labels: Record<string, string> = {
  accepting_orders: "Accepting orders · advertised",
  accepting_order_requests_advertised:
    "Order requests advertised · confirm acceptance",
  preorder: "Pre-order",
  listed_unconfirmed: "Listed · ordering unconfirmed",
  not_current: "Not verified as current",
  unverified: "Stock not verified",
  new_stock_listed: "New stock advertised · confirm exact vehicle",
  verified_new_stock: "Specific new stock verified",
};
export default function MarketAudit() {
  const [q, setQ] = useState(""),
    [status, setStatus] = useState("all"),
    [vehicleClass, setVehicleClass] = useState("all"),
    [limit, setLimit] = useState(24);
  const typedRecords =
    inventory.records as ((typeof inventory.records)[number] & {
      vehicleClass?: string;
    })[];
  const classLabels: Record<string, string> = {
    passenger: "Cars, SUVs & people movers",
    van: "Vans",
    ute: "Utes",
    truck: "Trucks",
    bus: "Buses",
    motorcycle: "Motorcycles & scooters",
    other: "Other / class to verify",
  };
  const records = typedRecords.filter(
    (r) =>
      matchesSearch(
        [r.brand, r.model, ...r.trims, ...(r.aliases ?? []), ...(r.modelAliases ?? [])].join(" "),
        q,
      ) &&
      (status === "all" || r.orderStatus === status) &&
      (vehicleClass === "all" || (r.vehicleClass || "other") === vehicleClass),
  );
  return (
    <main id="main" className="roadmark-discovery market-audit">
      <header className="container discovery-hero">
        <RoadmarkLogo />
        <p className="eyebrow">The market, with the gaps visible.</p>
        <h1>
          More choice.
          <br />
          <span>Less guesswork.</span>
        </h1>
        <p className="lede">
          A growing Australian new-EV audit beyond the original ten-family
          shortlist. A listing, an open order book and a car on a dealer’s
          forecourt are three different things.
        </p>
        <p className="discovery-scope">
          Checked {inventory.checkedAt} · {inventory.records.length} additional
          model records · Audit incomplete
        </p>
        <p className="small muted">
          Audit counts include uncertain, future-delivery and withdrawn
          listings. They are not a count of vehicles available to buy today.
          Motorcycles and scooters with cited supplier road-use claims are included; their full
          market coverage and specialist imports remain open.
        </p>
        <Link href="/">← Discover researched strengths</Link>
      </header>
      <section className="container discovery-content">
        <div className="market-filters">
          <label>
            Search the wider market
            <input
              type="search"
              value={q}
              onChange={(e) => {
                setQ(e.target.value);
                setLimit(24);
              }}
              placeholder="Brand, model or trim"
            />
          </label>
          <label>
            Vehicle type
            <select
              value={vehicleClass}
              onChange={(e) => {
                setVehicleClass(e.target.value);
                setLimit(24);
              }}
            >
              <option value="all">All vehicle types</option>
              {[...new Set(typedRecords.map((r) => r.vehicleClass || "other"))]
                .sort()
                .map((key) => (
                  <option key={key} value={key}>
                    {classLabels[key] || key}
                  </option>
                ))}
            </select>
          </label>
          <label>
            Order evidence
            <select
              value={status}
              onChange={(e) => {
                setStatus(e.target.value);
                setLimit(24);
              }}
            >
              <option value="all">All evidence states</option>
              {Object.entries(inventory.statusDefinitions).map(([key]) => (
                <option key={key} value={key}>
                  {labels[key]}
                </option>
              ))}
            </select>
          </label>
        </div>
        <p role="status">
          {records.length} model records. Exact-trim fact coverage varies;
          unverified measurements stay out of rankings.
        </p>
        <div className="market-records">
          {records.slice(0, limit).map((r) => (
            <article key={r.id}>
              <div className="discovery-car-top">
                <p className="eyebrow">{r.brand}</p>
                <span className="small muted">Checked {r.checkedAt}</span>
              </div>
              <p className="small muted">
                {classLabels[r.vehicleClass || "other"]}
              </p>
              <h2>{r.model}</h2>
              <p className="market-status">
                <strong>{labels[r.orderStatus] || r.orderStatus}</strong>
                <span>
                  {labels[r.stockStatus] || r.stockStatus.replaceAll("_", " ")}
                </span>
              </p>
              <h3>Named Australian configurations</h3>
              {r.trims.length ? (
                <ul>
                  {r.trims.map((t) => (
                    <li key={t}>{t}</li>
                  ))}
                </ul>
              ) : (
                <p>Exact trim names still need verification.</p>
              )}
              <p className="small muted">
                {r.trimCoverage.replaceAll("_", " ")}
              </p>
              <p>{buyerDisplayCopy(r.id, "evidenceNote", r.evidenceNote)}</p>
              <details>
                <summary>Evidence & limitations</summary>
                <ul>
                  {r.sourceUrls.map((u, i) => (
                    <li key={u}>
                      <a href={u} target="_blank" rel="noreferrer">
                        Source {i + 1} · {new URL(u).hostname} ↗
                      </a>
                    </li>
                  ))}
                </ul>
                <ul>
                  {r.limitations.map((l, i) => (
                    <li key={i}>{buyerDisplayCopy(r.id, `limitations[${i}]`, l)}</li>
                  ))}
                </ul>
              </details>
            </article>
          ))}
        </div>
        {!records.length && (
          <div className="discovery-empty">
            <h2>No matching audited records</h2>
            <p>
              This audit is incomplete; an empty result does not establish that
              a vehicle is unavailable.
            </p>
            <button
              className="button"
              onClick={() => {
                setQ("");
                setStatus("all");
                setVehicleClass("all");
                setLimit(24);
              }}
            >
              Clear filters
            </button>
          </div>
        )}
        {records.length > limit && (
          <div className="discovery-more">
            <p>
              Showing {limit} of {records.length} matching model records.
              Filters search the whole audit.
            </p>
            <button className="button" onClick={() => setLimit(limit + 24)}>
              Show 24 more records
            </button>
          </div>
        )}
        <section className="market-method">
          <h2>What this audit does and doesn’t establish</h2>
          <p>{inventory.scope}</p>
          <ul>
            {inventory.notes.map((n) => (
              <li key={n}>{n}</li>
            ))}
          </ul>
          <p>
            The growing detailed catalogue is available in discovery.
            Market-audit records alone do not enter rankings until their
            exact-trim measurements, comparable bases and supporting evidence
            pass review.
          </p>
          <h3>Reading availability</h3>
          <dl>
            {Object.entries(inventory.statusDefinitions).map(([key, note]) => (
              <div key={key}>
                <dt>{labels[key]}</dt>
                <dd>{note}</dd>
              </div>
            ))}
          </dl>
        </section>
      </section>
    </main>
  );
}

import { createCheckpoint99SourceReader, researchBeforeCheckpoint99, carsBeforeCheckpoint99 } from "./checkpoint99-history";
import { createRequire } from "node:module";
import { createCheckpoint96SourceReader } from "./checkpoint96-source-history";
import { createCheckpoint97SourceReader } from "./checkpoint97-source-history";
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import assert from "node:assert/strict";
import { catalogue, research } from "../../src/lib/data";
import { resolveBuyerProposal } from "../../src/lib/buyer-proposal-storage";
import type { SellingPointProposal } from "../../src/lib/selling-points";
import type { Car } from "../../src/lib/types";
const require = createRequire(import.meta.url);
const H = require("../../qa/checkpoint91/checkpoint91-harness.cjs");
const core = require("../../qa/checkpoint91/checkpoint91-history-core.cjs");
const dir = fileURLToPath(new URL("../../qa/checkpoint91/", import.meta.url));
const fixture = core.readRuntimeFixture(dir);
const f = H.loadFixtures(dir);
const readBefore99 = createCheckpoint99SourceReader((file) => readFileSync(new URL("../../" + file, import.meta.url)));
const read = (name: string) => JSON.parse(readBefore99(name).toString("utf8"));
// Verify97 first, then let the unchanged96 reader verify and recover its predecessors.
const readSourceBefore97 = createCheckpoint97SourceReader(readBefore99);
const readSourceBefore96 = createCheckpoint96SourceReader(readSourceBefore97);
// One input verification per test module instance; never accept post91 drift as a baseline.
for (const [file, pin] of Object.entries(f.pins) as [string, { sha256: string }][]) {
  if (file !== H.PROPOSAL_FILE && file !== H.LEDGER_FILE)
    assert.equal(H.sha(readSourceBefore96(file)), pin.sha256, file);
}
const previousStorage = H.freeze(core.previousStorage(read(H.PROPOSAL_FILE), read(H.LEDGER_FILE), fixture, f));
core.checkResearch(researchBeforeCheckpoint99(research()), fixture);
/** Verifies the complete approved+1 delta before any historical reconstruction. */
export function carsBeforeCheckpoint91(cars: Car[] = catalogue()): Car[] {
  return core.previousCars(carsBeforeCheckpoint99(cars), fixture) as Car[];
}
/** Removes only the exactly verified coordinated proposal+ledger append. */
export function dataBeforeCheckpoint91(file: string): Record<string, unknown> {
  if (file !== H.PROPOSAL_FILE && file !== H.LEDGER_FILE) return read(file);
  return structuredClone(file === H.PROPOSAL_FILE ? previousStorage.stored : previousStorage.ledger) as Record<string, unknown>;
}
/** Keep old policy-date counts on their exact historical proposal, never by changing328 to329. */
export function buyerProposalBeforeCheckpoint91(): SellingPointProposal {
  return resolveBuyerProposal(structuredClone(previousStorage.stored), structuredClone(previousStorage.ledger));
}

import { reconstructMarketBeforeCheckpoint99 } from "./helpers/checkpoint99-history";
import test from "node:test";
import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import { createElement, type ReactNode } from "react";
import { renderToStaticMarkup } from "react-dom/server";
import Discovery from "../src/components/discovery";
import Detail from "../src/components/detail";
import { WithEvidence } from "../src/components/with-evidence";
import { catalogue, pack, research } from "../src/lib/data";
import { buyerProposal } from "../src/lib/buyer-proposal";
import { buyerDisplayCopy } from "../src/lib/buyer-display-copy";
import { currentBuyerSummary } from "../src/lib/selling-points";
import currentInventory from "../src/lib/market-inventory-data";
const inventory = reconstructMarketBeforeCheckpoint99(currentInventory);
import type { Car, Source } from "../src/lib/types";
import { compiledSource } from "./helpers/compiled-source";

type Replacement = { id: string; field: string; before: string; after: string };
const { replacements } = JSON.parse(
  readFileSync(new URL("./fixtures/buyer-copy97.json", import.meta.url), "utf8"),
) as { replacements: Replacement[] };
const scopeRows = replacements.filter((r) => r.field === "configurationEvidence.projectionScope");
const marketRows = replacements.filter((r) => r.field !== "configurationEvidence.projectionScope");
const cars = catalogue();
const data = research();
const snapshot = { cars, data };
const escape = (text: string) => text.replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;").replaceAll('"', "&quot;").replaceAll("'", "&#x27;");
const hash = (value: unknown) => createHash("sha256").update(JSON.stringify(value)).digest("hex");
function render(node: ReactNode, sources: Source[] = data.sources) {
  // createElement's types do not infer a required prop from its positional child.
  // This test-only assertion is paired with the required node argument below.
  const props = { sources } as Parameters<typeof WithEvidence>[0];
  return renderToStaticMarkup(createElement(WithEvidence, props, node));
}

function marketHtml(records: typeof inventory.records) {
  const Component = compiledSource("src/components/market-audit.tsx", {
    "@/lib/market-inventory-data": { __esModule: true, default: { ...inventory, records } },
  }).default as () => ReactNode;
  return render(createElement(Component));
}

test("Discovery and exact detail display all six notices without changing their source objects", () => {
  for (const row of scopeRows) {
    const car = cars.find((c) => c.id === row.id)!;
    assert.ok(car, row.id);
    assert.equal(car.configurationEvidence!.projectionScope, row.before);
    const before = hash(car);
    const discovery = render(createElement(Discovery, { cars: [car], sources: data.sources }));
    const detail = render(createElement(Detail, { pack: pack(car.id, snapshot), criteria: data.criteria }));
    for (const html of [discovery, detail]) {
      assert.ok(html.includes(escape(row.after)), row.id);
      assert.ok(!html.includes(escape(row.before)), row.id);
      assert.match(html, /Captured configuration · specifications incomplete/);
    }
    assert.equal(hash(car), before);
    assert.equal(car.configurationEvidence!.rankingEligible, false);
    assert.equal(car.configurationEvidence!.completeVehicleCountEligible, false);
  }
});

test("Discovery revised and unknown records retain original copy and absent configurations stay absent", () => {
  const row = scopeRows[0];
  const original = cars.find((c) => c.id === row.id)!;
  const cases = [
    { ...original, id: `unknown-${original.id}` },
    { ...original, configurationEvidence: { ...original.configurationEvidence!, projectionScope: row.before + " Review changed." } },
  ];
  for (const car of cases) {
    const html = render(createElement(Discovery, { cars: [car], sources: data.sources }));
    assert.ok(html.includes(escape(car.configurationEvidence!.projectionScope)));
    assert.ok(!html.includes(escape(row.after)));
    assert.equal(car.configurationEvidence!.rankingEligible, false);
  }
  const without = { ...original, configurationEvidence: undefined };
  const html = render(createElement(Discovery, { cars: [without], sources: data.sources }));
  assert.doesNotMatch(html, /Captured configuration · specifications incomplete/);
  assert.ok(!html.includes(escape(row.after)));
});

test("Market renders only the four approved fields and preserves all adjacent limitations and sources", () => {
  const records = inventory.records.filter((r) => marketRows.some((row) => row.id === r.id));
  assert.equal(records.length, 3);
  const before = hash(inventory);
  for (const record of records) {
    const html = marketHtml([record]);
    const evidence = marketRows.find((r) => r.id === record.id && r.field === "evidenceNote");
    assert.ok(html.includes(escape(evidence?.after ?? record.evidenceNote)), record.id);
    for (const [i, limitation] of record.limitations.entries()) {
      const row = marketRows.find((r) => r.id === record.id && r.field === `limitations[${i}]`);
      if (row) {
        assert.equal(limitation, row.before);
        assert.ok(html.includes(escape(row.after)), row.id);
        assert.ok(!html.includes(escape(row.before)), row.id);
      } else assert.ok(html.includes(escape(limitation)), `${record.id} limitation ${i}`);
    }
    for (const url of record.sourceUrls) assert.ok(html.includes(escape(url)), url);
    assert.ok(html.includes(record.checkedAt));
  }
  assert.equal(hash(inventory), before);
});

test("Market changed IDs, positions and wording retain their original unreviewed strings", () => {
  const record = inventory.records.find((r) => r.id === "mazda-cx-6e")!;
  const rows = marketRows.filter((r) => r.id === record.id);
  const unknown = { ...record, id: "unknown-cx-6e" };
  const unknownHtml = marketHtml([unknown]);
  for (const row of rows) {
    assert.ok(unknownHtml.includes(escape(row.before)));
    assert.ok(!unknownHtml.includes(escape(row.after)));
  }
  const moved = { ...record, limitations: ["Additional warning", ...record.limitations], evidenceNote: record.evidenceNote + " Revised." };
  const movedHtml = marketHtml([moved]);
  for (const row of rows) {
    assert.ok(movedHtml.includes(escape(row.before)));
    assert.ok(!movedHtml.includes(escape(row.after)));
  }
  assert.equal(moved.stockStatus, record.stockStatus);
  assert.equal(moved.orderStatus, record.orderStatus);
});

test("guarded identities, buyer summaries and freshness outcomes remain untouched by display formatting", () => {
  const guarded = scopeRows.filter((row) => buyerProposal.records.some((r) => r.variantId === row.id));
  assert.equal(guarded.length, 4);
  const before = hash({ cars, proposal: buyerProposal, sources: data.sources });
  for (const row of guarded) {
    const car = cars.find((c) => c.id === row.id)!;
    const approved = buyerProposal.records.find((r) => r.variantId === row.id)!;
    assert.deepEqual(car.configurationEvidence, approved.expectedIdentity!.configurationEvidence);
    for (const asOf of ["2026-10-12", "2026-12-31", "invalid"]) {
      const prior = currentBuyerSummary(car.buyerSummary, data.sources, { asOf, maxAgeDays: 30 });
      assert.equal(buyerDisplayCopy(car.id, row.field, car.configurationEvidence!.projectionScope), row.after);
      assert.deepEqual(currentBuyerSummary(car.buyerSummary, data.sources, { asOf, maxAgeDays: 30 }), prior);
    }
    assert.equal(car.configurationEvidence!.projectionScope, row.before);
  }
  assert.equal(hash({ cars, proposal: buyerProposal, sources: data.sources }), before);
});

test("pre-clock Discovery keeps the existing evidence fallback and does not reveal buyer claims", () => {
  const row = scopeRows[0];
  const original = cars.find((c) => c.id === row.id)!;
  const source: Source = {
    id: "copy97-clock-proof",
    url: "https://example.com/evidence",
    title: "Clock test evidence",
    publisher: "Test fixture",
    source_type: "audit",
    published_date: null,
    accessed_date: "2026-10-10",
    market: "AU",
    supports: "Synthetic clock-bound display test",
  };
  const car: Car = {
    ...original,
    buyerSummary: {
      checkedAt: "2026-10-10",
      guardSourceIds: [source.id],
      conditions: [],
      strength: { label: "CLOCK-BOUND-LABEL", text: "CLOCK-BOUND-TEXT", sourceIds: [source.id] },
    },
  };
  const sources = [...data.sources, source];
  assert.ok(currentBuyerSummary(car.buyerSummary, sources, { asOf: "2026-10-10", maxAgeDays: 30 })?.strength);
  const html = render(createElement(Discovery, { cars: [car], sources }), sources);
  assert.ok(html.includes(escape(row.after)));
  assert.match(html, /Comparable evidence is still incomplete/);
  assert.doesNotMatch(html, /CLOCK-BOUND-LABEL|CLOCK-BOUND-TEXT|Checking evidence freshness/);
});

test("portable routes use the same component display layer without rewriting packed evidence", () => {
  const entry = readFileSync(new URL("../src/portable/entry.tsx", import.meta.url), "utf8");
  assert.match(entry, /import Discovery from "@\/components\/discovery"/);
  assert.match(entry, /import MarketAudit from "@\/components\/market-audit"/);
  const build = readFileSync(new URL("../scripts/build-portable.ts", import.meta.url), "utf8");
  assert.doesNotMatch(build, /buyerDisplayCopy|buyer-display-copy/);
  const projection = readFileSync(new URL("../src/lib/discovery.ts", import.meta.url), "utf8");
  assert.match(projection, /projectionScope: car\.configurationEvidence\.projectionScope/);
  assert.doesNotMatch(projection, /buyerDisplayCopy|buyer-display-copy/);
});

import test from "node:test";
import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import { createCheckpoint97SourceReader } from "./helpers/checkpoint97-source-history";
import {
  createCheckpoint96SourceReader,
  sourceBeforeCheckpoint96,
} from "./helpers/checkpoint96-source-history";

const discovery = "src/components/discovery.tsx";
const portable = "src/portable/link.tsx";
const files = [discovery, portable];
const read = createCheckpoint97SourceReader((file) =>
  readFileSync(new URL("../" + file, import.meta.url)),
);
const sha = (bytes: Uint8Array) =>
  createHash("sha256").update(bytes).digest("hex");
const expected = [
  { sha256: "c382047506d1881d4483e6478757dca41fc6d8011855e151027df027f689aa6f", bytes: 26192 },
  { sha256: "0add93ac8b2209b4cba733f805d3bfb7f9252fd3d33bd0d9b3da65c95a8ecfe6", bytes: 647 },
];
function replaceOne(source: string, from: string, to: string) {
  assert.equal(source.split(from).length, 2, from);
  return Buffer.from(source.replace(from, to));
}

test("approved96 sources reconstruct exact checkpoint95 bytes and the original91 Discovery pin", () => {
  for (const [index, file] of files.entries()) {
    const current = read(file);
    const original = Buffer.from(current);
    const previous = sourceBeforeCheckpoint96(file, current);
    assert.equal(sha(previous), expected[index].sha256);
    assert.equal(previous.length, expected[index].bytes);
