  clear.props.onClick();
  assert.deepEqual(h.state, ["", "all", "all", 24]);
  const nodes = h.render();
  assert.equal(nodes.filter(n => n.type === "article").length, 24);
  assert.deepEqual(nodes.filter(n => n.type === "select").map(n => n.props.value), ["all", "all"]);
  assert.ok(!nodes.some(n => n.type === "button" && n.props.children === "Clear filters"));
  clear.props.onClick();
  assert.deepEqual(h.state, ["", "all", "all", 24]);
});

